# 数据处理
i = 0
raws = []
for samp in samples:
    instruction = samp['instruction']
    input = json.dumps(json.loads(samp['input']), ensure_ascii=False)
    output = json.dumps(json.loads(samp['output']), ensure_ascii=False)
    raws.append({'id':i, 'instruction': instruction, 'input': input, 'output': output})
    i = i + 1

# 数据保存
df = pd.DataFrame(raws, columns=['id', 'instruction', 'input', 'output'])
df.to_csv('test_data.csv', index=False)


